package com.GroupAttendanceTracker;

import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.List;

@Singleton
public class GroupAttendanceTrackerOverlay extends OverlayPanel
{
    private final GroupAttendanceTrackerPlugin plugin;
    private final GroupAttendanceTrackerConfig config;

    @Inject
    private GroupAttendanceTrackerOverlay(GroupAttendanceTrackerPlugin plugin, GroupAttendanceTrackerConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        // ✅ allow Alt-drag & snapping
        setMovable(true);
        setSnappable(true);
        setDragTargetable(true);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        List<String> names = plugin.getVisibleNames();

        // Title
        String title = "Nearby Players";
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text(title)
                        .color(Color.WHITE)
                        .build()
        );

        // Count
        if (config.showCount())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Count:")
                            .right(Integer.toString(names.size()))
                            .leftColor(Color.LIGHT_GRAY)
                            .rightColor(Color.CYAN)
                            .build()
            );
        }

        if (names.isEmpty())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("No players")
                            .right("")
                            .leftColor(Color.GRAY)
                            .build()
            );
        }
        else
        {
            int index = 1;
            for (String name : names)
            {
                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left(index + ".")
                                .right(name)
                                .leftColor(Color.LIGHT_GRAY)
                                .rightColor(Color.GREEN)
                                .build()
                );
                index++;
            }
        }

        return super.render(graphics);
    }
}

package com.GroupAttendanceTracker;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;


@Slf4j
@PluginDescriptor(
        name = "Group Attendance Tracker",
        description = "Track Group/Event attendance using world views",
        tags = {"clan", "attendance", "group"}
)
public class GroupAttendanceTrackerPlugin extends Plugin
{
    private static final String CONFIG_GROUP_KEY = "GroupAttendanceTracker";
    private static final String DATA_KEY = "attendanceData";
    private static final int SAVE_INTERVAL_TICKS = 50;
    private static final BufferedImage ICON = createListIcon();

    @Inject
    private Client client;

    @Inject
    private GroupAttendanceTrackerConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private GroupAttendanceTrackerOverlay overlay;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private GroupAttendanceTrackerPanel panel;

    @Inject
    private ConfigManager configManager;

    private NavigationButton navButton;

    @Getter
    private List<String> visibleNames = Collections.emptyList();

    private final Map<String, Integer> attendanceTicks = new HashMap<>();
    private Set<String> lastLoggedSet = new HashSet<>();
    private boolean trackingEnabled;
    private int ticksSinceLastSave = 0;

    @Provides
    GroupAttendanceTrackerConfig provideConfig(ConfigManager cm)
    {
        return cm.getConfig(GroupAttendanceTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        log.info("Group Attendance plugin started");
        visibleNames = Collections.emptyList();
        lastLoggedSet.clear();
        ticksSinceLastSave = 0;

        trackingEnabled = config.trackingEnabled();

        loadAttendance();

        if (config.showOverlay())
        {
            overlayManager.add(overlay);
        }

        panel.setPlugin(this);

        navButton = NavigationButton.builder()
                .tooltip("Group Attendance")
                .priority(5)
                .icon(ICON)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        final String text = attendanceTicks.isEmpty()
                ? "No attendance yet."
                : buildAttendanceText();
        SwingUtilities.invokeLater(() -> panel.updateAttendanceText(text));
    }

    @Override
    protected void shutDown()
    {
        log.info("Group Attendance plugin stopped");

        saveAttendance();

        overlayManager.remove(overlay);

        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }

        visibleNames = Collections.emptyList();
        attendanceTicks.clear();
        lastLoggedSet.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null)
        {
            log.info("Attendance: logged in as {}", client.getLocalPlayer().getName());
        }

        if (event.getGameState() == GameState.LOGIN_SCREEN
                || event.getGameState() == GameState.HOPPING)
        {
            saveAttendance();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals(CONFIG_GROUP_KEY))
        {
            return;
        }

        if ("showOverlay".equals(event.getKey()))
        {
            if (config.showOverlay())
            {
                overlayManager.add(overlay);
            }
            else
            {
                overlayManager.remove(overlay);
            }
        }
        else if ("trackingEnabled".equals(event.getKey()))
        {
            trackingEnabled = config.trackingEnabled();

            if (!trackingEnabled)
            {
                visibleNames = Collections.emptyList();
                saveAttendance();
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        if (!trackingEnabled)
        {
            return;
        }

        final Player local = client.getLocalPlayer();
        if (local == null)
        {
            visibleNames = Collections.emptyList();
            return;
        }

        final WorldView rootView = client.getTopLevelWorldView();
        if (rootView == null)
        {
            visibleNames = Collections.emptyList();
            return;
        }

        List<Player> allPlayers = new ArrayList<>();
        collectPlayersRecursive(rootView, allPlayers);

        List<String> filteredNames = new ArrayList<>();

        for (Player p : allPlayers)
        {
            if (p == null)
            {
                continue;
            }

            String name = p.getName();
            boolean isLocalPlayer = (p == local);
            boolean isNameInFilter = false;

            if (isLocalPlayer)
            {
                isNameInFilter = config.trackSelf();
            }
            else if (config.ClanChat() && p.isClanMember())
            {
                isNameInFilter = true;
            }
            else if (config.FriendsChat() && p.isFriendsChatMember())
            {
                isNameInFilter = true;
            }
            else if (config.GuestClanChat() && isGuestClanMember(name))
            {
                isNameInFilter = true;
            }
            else if (config.PublicChat())
            {
                isNameInFilter = true;
            }

            if (name != null && !name.isEmpty() && isNameInFilter)
            {
                filteredNames.add(name);
            }
        }

        if (config.sortAlphabetically())
        {
            filteredNames.sort(String.CASE_INSENSITIVE_ORDER);
        }

        Set<String> filteredSet = new HashSet<>(filteredNames);

        for (String name : filteredSet)
        {
            attendanceTicks.merge(name, 1, Integer::sum);
        }

        int max = Math.max(1, config.maxPlayers());
        List<String> overlayNames;
        if (filteredNames.size() > max)
        {
            overlayNames = new ArrayList<>(filteredNames.subList(0, max));
        }
        else
        {
            overlayNames = new ArrayList<>(filteredNames);
        }

        visibleNames = Collections.unmodifiableList(overlayNames);

        final String attendanceText = buildAttendanceText();
        SwingUtilities.invokeLater(() -> panel.updateAttendanceText(attendanceText));

        ticksSinceLastSave++;
        if (ticksSinceLastSave >= SAVE_INTERVAL_TICKS)
        {
            saveAttendance();
            ticksSinceLastSave = 0;
        }
    }

    private boolean isGuestClanMember(String name)
    {
        if (name == null)
        {
            return false;
        }
        ClanChannel guestClan = client.getGuestClanChannel();
        return guestClan != null && guestClan.findMember(name) != null;
    }

    private void collectPlayersRecursive(WorldView worldView, List<Player> out)
    {
        for (Player p : worldView.players())
        {
            if (p != null)
            {
                out.add(p);
            }
        }

        for (WorldView child : worldView.worldViews())
        {
            collectPlayersRecursive(child, out);
        }
    }

    private String buildAttendanceText()
    {
        if (attendanceTicks.isEmpty())
        {
            return "Group attendance (0)\nNo players currently tracked.";
        }

        List<Map.Entry<String, Integer>> entries = new ArrayList<>(attendanceTicks.entrySet());
        entries.sort(Comparator
                .comparingInt((Map.Entry<String, Integer> e) -> e.getValue()).reversed()
                .thenComparing(Map.Entry::getKey, String.CASE_INSENSITIVE_ORDER));

        StringBuilder sb = new StringBuilder();
        sb.append("Group attendance (").append(entries.size()).append(")\n");

        for (Map.Entry<String, Integer> e : entries)
        {
            String name = e.getKey();
            int ticks = e.getValue();
            String duration = formatDurationTicks(ticks);
            sb.append(name).append(" - ").append(duration).append('\n');
        }

        return sb.toString();
    }

    private static String formatDurationTicks(int ticks)
    {
        long totalMillis = ticks * 600L;
        long totalSeconds = totalMillis / 1000L;
        long minutes = totalSeconds / 60L;
        long seconds = totalSeconds % 60L;
        return String.format("%02d:%02d", minutes, seconds);
    }

    // --- Persistence ---

    private void saveAttendance()
    {
        if (attendanceTicks.isEmpty())
        {
            configManager.unsetConfiguration(CONFIG_GROUP_KEY, DATA_KEY);
            return;
        }

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Integer> entry : attendanceTicks.entrySet())
        {
            if (sb.length() > 0)
            {
                sb.append(';');
            }
            sb.append(entry.getKey()).append('=').append(entry.getValue());
        }

        configManager.setConfiguration(CONFIG_GROUP_KEY, DATA_KEY, sb.toString());
        log.debug("Saved attendance for {} players", attendanceTicks.size());
    }

    private void loadAttendance()
    {
        attendanceTicks.clear();

        String data = configManager.getConfiguration(CONFIG_GROUP_KEY, DATA_KEY);
        if (data == null || data.isEmpty())
        {
            return;
        }

        for (String entry : data.split(";"))
        {
            int eq = entry.lastIndexOf('=');
            if (eq < 1)
            {
                continue;
            }

            String name = entry.substring(0, eq);
            try
            {
                int ticks = Integer.parseInt(entry.substring(eq + 1));
                attendanceTicks.put(name, ticks);
            }
            catch (NumberFormatException e)
            {
                log.warn("Skipping malformed attendance entry: {}", entry);
            }
        }

        log.info("Loaded attendance for {} players", attendanceTicks.size());
    }

    // --- Icon ---

    private static BufferedImage createListIcon()
    {
        int size = 16;
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();

        g.setColor(new Color(0x2a1800));
        g.fillRect(1, 3, 13, 11);

        g.setColor(new Color(0x5a0000));
        g.fillRect(1, 3, 13, 4);

        g.setColor(new Color(0xc03020));
        g.fillRect(2, 3, 11, 1);

        g.setColor(new Color(0xc8a030));
        g.fillRect(4, 1, 2, 4);
        g.fillRect(10, 1, 2, 4);

        g.setColor(new Color(0xffe060));
        g.fillRect(4, 1, 1, 1);
        g.fillRect(10, 1, 1, 1);

        g.setColor(new Color(0xc8a030));
        g.fillRect(2, 9, 2, 2);
        g.fillRect(6, 9, 2, 2);
        g.fillRect(10, 9, 2, 2);

        g.setColor(new Color(0x4a3010));
        g.fillRect(2, 12, 2, 1);
        g.fillRect(6, 12, 2, 1);
        g.fillRect(10, 12, 2, 1);

        g.setColor(new Color(0xffe060));
        g.fillRect(2, 9, 1, 1);
        g.fillRect(6, 9, 1, 1);
        g.fillRect(10, 9, 1, 1);

        g.setColor(new Color(0xc8a030));
        g.drawRect(1, 3, 12, 10);

        g.dispose();
        return img;
    }

    public Map<String, Integer> getAttendanceTicks()
    {
        return Collections.unmodifiableMap(attendanceTicks);
    }

    public static class AttendanceRecord
    {
        private final String name;
        private final int ticks;

        public AttendanceRecord(String name, int ticks)
        {
            this.name = name;
            this.ticks = ticks;
        }

        public String getName()
        {
            return name;
        }

        public int getTicks()
        {
            return ticks;
        }
    }

    void resetAttendance()
    {
        attendanceTicks.clear();
        visibleNames = Collections.emptyList();
        lastLoggedSet.clear();

        configManager.unsetConfiguration(CONFIG_GROUP_KEY, DATA_KEY);

        SwingUtilities.invokeLater(() -> panel.updateAttendanceText("No attendance yet."));
    }
}

package com.GroupAttendanceTracker;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.datatransfer.StringSelection;

@Singleton
public class GroupAttendanceTrackerPanel extends PluginPanel
{
    private static final String CONFIG_GROUP = "GroupAttendanceTracker";

    private static final Color BUTTON_COLOR = new Color(60, 60, 60);
    private static final Color START_HOVER = new Color(45, 120, 45);
    private static final Color STOP_HOVER = new Color(140, 45, 45);
    private static final Color RESET_HOVER = new Color(140, 110, 30);
    private static final Color COPY_HOVER = new Color(45, 90, 140);
    private static final Color SEPARATOR_COLOR = new Color(70, 70, 70);

    private final GroupAttendanceTrackerConfig config;
    private final ConfigManager configManager;

    private final JPanel listContainer = new JPanel();
    private final JLabel countLabel = new JLabel("0 players tracked");
    private final JButton startButton = new JButton("Start");
    private final JButton stopButton = new JButton("Stop");
    private final JButton resetButton = new JButton("Reset");
    private final JButton copyButton = new JButton("Copy to Clipboard");

    private final JScrollPane scrollPane;

    private GroupAttendanceTrackerPlugin plugin;
    private String lastRawText = "";

    @Inject
    GroupAttendanceTrackerPanel(GroupAttendanceTrackerConfig config, ConfigManager configManager)
    {
        super(false);

        this.config = config;
        this.configManager = configManager;

        setLayout(new BorderLayout(0, 0));
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel topSection = new JPanel();
        topSection.setLayout(new BoxLayout(topSection, BoxLayout.Y_AXIS));
        topSection.setOpaque(false);

        JPanel header = buildHeader();
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        JPanel controls = buildControls();
        controls.setAlignmentX(Component.LEFT_ALIGNMENT);
        JPanel countBar = buildCountBar();
        countBar.setAlignmentX(Component.LEFT_ALIGNMENT);

        topSection.add(header);
        topSection.add(Box.createVerticalStrut(8));
        topSection.add(controls);
        topSection.add(Box.createVerticalStrut(8));
        topSection.add(countBar);
        topSection.add(Box.createVerticalStrut(4));

        add(topSection, BorderLayout.NORTH);

        listContainer.setLayout(new BoxLayout(listContainer, BoxLayout.Y_AXIS));
        listContainer.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        scrollPane = new JScrollPane(listContainer);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        add(scrollPane, BorderLayout.CENTER);

        add(buildFooter(), BorderLayout.SOUTH);

        updateButtonStates(config.trackingEnabled());
    }

    private JPanel buildHeader()
    {
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setOpaque(false);

        JLabel title = new JLabel("Group Attendance");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(ColorScheme.BRAND_ORANGE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel subtitle = new JLabel("Track attendance for your group.");
        subtitle.setFont(FontManager.getRunescapeSmallFont());
        subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        subtitle.setAlignmentX(Component.LEFT_ALIGNMENT);

        header.add(title);
        header.add(Box.createVerticalStrut(2));
        header.add(subtitle);

        return header;
    }

    private JPanel buildControls()
    {
        JPanel controls = new JPanel(new GridLayout(1, 3, 4, 0));
        controls.setOpaque(false);
        controls.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

        styleButton(startButton, START_HOVER);
        styleButton(stopButton, STOP_HOVER);
        styleButton(resetButton, RESET_HOVER);

        startButton.addActionListener(e -> setTracking(true));
        stopButton.addActionListener(e -> setTracking(false));
        resetButton.addActionListener(e -> resetAttendance());

        controls.add(startButton);
        controls.add(stopButton);
        controls.add(resetButton);

        return controls;
    }

    private JPanel buildCountBar()
    {
        JPanel bar = new JPanel(new BorderLayout());
        bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        bar.setBorder(new EmptyBorder(4, 6, 4, 6));
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));

        countLabel.setFont(FontManager.getRunescapeSmallFont());
        countLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        bar.add(countLabel, BorderLayout.WEST);
        return bar;
    }

    private JPanel buildFooter()
    {
        JPanel footer = new JPanel(new BorderLayout());
        footer.setOpaque(false);
        footer.setBorder(new EmptyBorder(6, 0, 150, 0));

        styleButton(copyButton, COPY_HOVER);
        copyButton.addActionListener(e -> copyAttendanceToClipboard());

        footer.add(copyButton, BorderLayout.CENTER);
        return footer;
    }

    private void styleButton(JButton button, Color hoverColor)
    {
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setFocusable(false);
        button.setForeground(Color.WHITE);
        button.setBackground(BUTTON_COLOR);
        button.setBorder(new EmptyBorder(5, 8, 5, 8));
        button.setOpaque(true);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        button.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent e)
            {
                if (button.isEnabled())
                {
                    button.setBackground(hoverColor);
                }
            }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e)
            {
                button.setBackground(button.isEnabled() ? BUTTON_COLOR : BUTTON_COLOR.darker());
            }
        });
    }

    private void setTracking(boolean enabled)
    {
        configManager.setConfiguration(CONFIG_GROUP, "trackingEnabled", enabled);
        updateButtonStates(enabled);
    }

    private void resetAttendance()
    {
        if (plugin != null)
        {
            plugin.resetAttendance();
        }
        else
        {
            listContainer.removeAll();
            listContainer.revalidate();
            listContainer.repaint();
        }
    }

    private void updateButtonStates(boolean trackingEnabled)
    {
        startButton.setEnabled(!trackingEnabled);
        stopButton.setEnabled(trackingEnabled);
        startButton.setBackground(trackingEnabled ? BUTTON_COLOR.darker() : BUTTON_COLOR);
        stopButton.setBackground(trackingEnabled ? BUTTON_COLOR : BUTTON_COLOR.darker());
    }

    private void copyAttendanceToClipboard()
    {
        String text = lastRawText;
        if (text == null || text.isEmpty())
        {
            text = "";
        }
        StringSelection selection = new StringSelection(text);
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, selection);
    }

    void updateAttendanceText(String text)
    {
        lastRawText = (text == null) ? "" : text;

        listContainer.removeAll();

        if (text == null || text.isEmpty() || text.startsWith("No attendance"))
        {
            countLabel.setText("0 players tracked");
            JLabel empty = new JLabel("No players tracked yet.");
            empty.setFont(FontManager.getRunescapeSmallFont());
            empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            empty.setBorder(new EmptyBorder(12, 8, 12, 8));
            empty.setHorizontalAlignment(SwingConstants.CENTER);
            empty.setAlignmentX(Component.CENTER_ALIGNMENT);
            listContainer.add(empty);
        }
        else
        {
            String[] lines = text.split("\n");
            int playerCount = 0;

            for (String line : lines)
            {
                if (line.startsWith("Group attendance"))
                {
                    continue;
                }

                String trimmed = line.trim();
                if (trimmed.isEmpty())
                {
                    continue;
                }

                int dashIdx = trimmed.lastIndexOf(" - ");
                if (dashIdx < 0)
                {
                    continue;
                }

                String name = trimmed.substring(0, dashIdx).trim();
                String duration = trimmed.substring(dashIdx + 3).trim();
                playerCount++;

                if (playerCount > 1)
                {
                    JSeparator sep = new JSeparator(SwingConstants.HORIZONTAL);
                    sep.setForeground(SEPARATOR_COLOR);
                    sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
                    listContainer.add(sep);
                }

                listContainer.add(buildPlayerRow(playerCount, name, duration));
            }

            countLabel.setText(playerCount + (playerCount == 1 ? " player" : " players") + " tracked");
        }

        listContainer.revalidate();
        listContainer.repaint();
        scrollPane.revalidate();
    }

    private JPanel buildPlayerRow(int rank, String name, String duration)
    {
        JPanel row = new JPanel(new BorderLayout());
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(4, 6, 4, 6));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

        JLabel rankLabel = new JLabel(rank + ". ");
        rankLabel.setFont(FontManager.getRunescapeSmallFont());
        rankLabel.setForeground(new Color(140, 140, 140));
        rankLabel.setPreferredSize(new Dimension(22, 16));

        JLabel nameLabel = new JLabel(name);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setForeground(Color.WHITE);

        JLabel durationLabel = new JLabel(duration);
        durationLabel.setFont(FontManager.getRunescapeSmallFont());
        durationLabel.setForeground(ColorScheme.BRAND_ORANGE);

        JPanel leftSide = new JPanel(new BorderLayout());
        leftSide.setOpaque(false);
        leftSide.add(rankLabel, BorderLayout.WEST);
        leftSide.add(nameLabel, BorderLayout.CENTER);

        row.add(leftSide, BorderLayout.CENTER);
        row.add(durationLabel, BorderLayout.EAST);

        return row;
    }

    void setAttendanceText(String text)
    {
        updateAttendanceText(text);
    }

    void setPlugin(GroupAttendanceTrackerPlugin plugin)
    {
        this.plugin = plugin;
    }
}

